const image=v=>safeImage(v)?'<img src="'+esc(v)+'" alt="">':'';
const appIcon=id=>{const a=APPS.find(v=>v.id===id)||APPS[0];return '<span class="ap-app-icon" style="--ix:'+([5,35,65,95][a.col])+'%;--iy:'+([4.5,32.1,60.1,87.9][a.row])+'%" aria-hidden="true"></span>';};
