  return head('Drift',b(ico('clock-rotate-left'),'browser-history','','ap-icon-button')+b(ico('plus'),'browser-tab','','ap-icon-button'))+'<div class="ap-browser-tabs">'+p().browser.tabs.map(tab=>b(esc(tab.url.replace('drift://','')),'browser-switch',attr('id',tab.id)+' aria-pressed="'+(tab.id===p().browser.activeTab)+'"')+b('×','browser-close',attr('id',tab.id),'ap-tab-close')).join('')+'</div><main class="ap-body">'+body+'</main><form data-phone-form="browser" class="ap-browser-bar">'+ico('lock')+'<input name="url" value="'+esc(url)+'" aria-label="'+t('ที่อยู่เว็บในโลกของโรล','In-world address')+'"><button type="submit" aria-label="Go">'+ico('arrow-right')+'</button>'+b(ico('bookmark'),'browser-bookmark',attr('url',url),'ap-icon-button')+'</form>';
