  setHTML(target,cfg().capsule?ico(call?'phone':d.working?'ellipsis':'message')+'<span><strong>'+esc(title)+'</strong><small>'+esc(sub.slice(0,45))+'</small></span>'+(call?.status==='connected'?'<span class="ap-wave"><i></i><i></i><i></i><i></i></span>':''):'');
