   openSheet(t('ข้อความ','Message'),b(t('ตอบกลับ','Reply'),'message-reply',attr('id',m.id),'ap-menu-item')+b(m.pinned?t('เลิกปักหมุด','Unpin'):t('ปักหมุด','Pin'),'message-pin',attr('id',m.id),'ap-menu-item')+(m.from==='player'?b(t('แก้ไข','Edit'),'message-edit',attr('id',m.id),'ap-menu-item'):'')+b(t('ลบข้อความ','Delete message'),'message-delete',attr('id',m.id),'ap-danger ap-wide'));return;
